/**
 * A procurement awards report that reuses supplier sites and certificates, buyer contacts, and commodity
 * classifications across awards. The deepest OPTIONAL chain follows a site address through geography to the authority
 * administering a trade agreement. The two publication channels per award produce duplicate projected rows. At the
 * default scale, DISTINCT reduces 43.2 million candidate rows to 21.6 million twenty-column results.
 */
@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 1)
@Measurement(iterations = 3)
@Fork(value = 1, jvmArgsAppend = "-Xmx12g")
public class LmdbNestedOptionalDistinctBenchmark {

	private static final String NS = "urn:rdf4j:lmdb:procurement:";
	private static final int PROJECTION_WIDTH = 20;
	private static final long MAP_SIZE = 512L * 1024 * 1024;
	private static final String QUERY = """
			PREFIX pc: <urn:rdf4j:lmdb:procurement:>
			SELECT DISTINCT ?award ?supplier ?buyer ?category
			                ?site ?street ?city ?region ?country ?tradeArea ?tradeAgreement ?tradeAuthority
			                ?certificate ?standard ?issuer ?accreditation ?contact ?contactEmail ?division ?sector
			WHERE {
			  ?award pc:awardedTo ?supplier ;
			         pc:contractingAuthority ?buyer ;
			         pc:commodityCategory ?category ;
			         pc:publishedThrough ?channel .
			  OPTIONAL {
			    ?supplier pc:operatesSite ?site .
			    OPTIONAL {
			      ?site pc:postalAddress ?address .
			      OPTIONAL { ?address pc:streetAddress ?street . }
			      OPTIONAL {
			        ?address pc:locality ?city .
			        OPTIONAL {
			          ?city pc:administrativeRegion ?region .
			          OPTIONAL {
			            ?region pc:inCountry ?country .
			            OPTIONAL {
			              ?country pc:memberOfTradeArea ?tradeArea .
			              OPTIONAL {
			                ?tradeArea pc:procurementAgreement ?tradeAgreement .
			                OPTIONAL { ?tradeAgreement pc:administeredBy ?tradeAuthority . }
			              }
			            }
			          }
			        }
			      }
			    }
			  }
			  OPTIONAL {
			    ?supplier pc:holdsCertificate ?certificate .
			    OPTIONAL { ?certificate pc:certifiesStandard ?standard . }
			    OPTIONAL {
			      ?certificate pc:issuedBy ?issuer .
			      OPTIONAL { ?issuer pc:accreditedBy ?accreditation . }
			    }
			  }
			  OPTIONAL {
			    ?buyer pc:procurementContact ?contact .
			    OPTIONAL { ?contact pc:email ?contactEmail . }
			  }
			  OPTIONAL {
			    ?category pc:commodityFamily ?family .
			    OPTIONAL {
			      ?family pc:commodityDivision ?division .
			      OPTIONAL { ?division pc:commoditySector ?sector . }
			    }
			  }
			}
			""";

	@Param("200000")
	public int awardCount;

	private File dataDirectory;
	private SailRepository repository;
	private long expectedRows;

	@Setup(Level.Trial)
	public void setUp() throws IOException {
		if (awardCount <= 0) {
			throw new IllegalArgumentException("awardCount must be positive");
		}
		dataDirectory = Files.createTempDirectory("rdf4j-lmdb-nested-optional-distinct-").toFile();
		try {
			LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc,posc")
					.setNativeEvaluationEnabled(true)
					.setDirectAdjacencyEnabled(true)
					.setTripleDBSize(MAP_SIZE)
					.setValueDBSize(MAP_SIZE)
					.setForceSync(false);
			repository = new SailRepository(new LmdbStore(dataDirectory, config));
			repository.init();
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				ProcurementFixture fixture = new ProcurementFixture(connection);
				fixture.addGeography();
				fixture.addSuppliers();
				fixture.addBuyers();
				fixture.addCommodityTaxonomy();
				expectedRows = fixture.addAwards(awardCount);
				connection.commit();
				System.out.printf("Setup complete with %,d triples and %,d expected distinct rows%n",
						connection.size(), expectedRows);
			}

			try (RepositoryConnection connection = repository.getConnection()) {
				try (TupleQueryResult evaluate = connection
						.prepareTupleQuery("SELECT (COUNT(*) AS ?count) WHERE { ?s a ?o }")
						.evaluate()) {
					while (evaluate.hasNext()) {
						System.out.printf("Type count: %,d%n",
								((IntegerLiteral) evaluate.next().getValue("count")).intValue());
					}
				}
			}
			try {
				Thread.sleep(1000); // give the OS a moment to flush the file system buffers

			} catch (InterruptedException e) {
				throw new RuntimeException(e);
			}

			try (RepositoryConnection connection = repository.getConnection()) {
				try (TupleQueryResult evaluate = connection
						.prepareTupleQuery("SELECT (COUNT(*) AS ?count) WHERE { ?s ?p ?o }")
						.evaluate()) {
					while (evaluate.hasNext()) {
						System.out.printf("Triple count: %,d%n",
								((IntegerLiteral) evaluate.next().getValue("count")).intValue());
					}
				}
			}

		} catch (RuntimeException | Error failure) {
			try {
				tearDown();
			} catch (RuntimeException | Error cleanupFailure) {
				failure.addSuppressed(cleanupFailure);
			}
			throw failure;
		}

		System.out.println(QUERY);
	}

	@Benchmark
	public long nestedOptionalDistinct() {
		long rows = 0;
		try (RepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(QUERY).evaluate()) {
			if (result.getBindingNames().size() != PROJECTION_WIDTH) {
				throw new IllegalStateException("Unexpected projection: " + result.getBindingNames());
			}
			while (result.hasNext()) {
				result.next();
				rows++;
			}
		}
		if (rows != expectedRows) {
			throw new IllegalStateException("Expected " + expectedRows + " distinct rows, returned " + rows);
		}
		return rows;
	}

	@TearDown(Level.Trial)
	public void tearDown() {
		try {
			if (repository != null) {
				repository.shutDown();
			}
		} finally {
			repository = null;
			if (dataDirectory != null) {
				LmdbTestUtil.deleteDir(dataDirectory);
				dataDirectory = null;
			}
		}
	}

	private static final class ProcurementFixture {
		private static final int SUPPLIER_COUNT = 400;
		private static final int BUYER_COUNT = 80;
		private static final int CATEGORY_COUNT = 160;
		private static final int CONTACTS_PER_BUYER = 3;
		private static final int MAX_SITES_PER_SUPPLIER = 7;
		private static final int CITY_COUNT = 48;
		private static final int REGION_COUNT = 12;
		private static final int COUNTRY_COUNT = 6;
		private static final int TRADE_AREA_COUNT = 3;
		private static final int ISSUER_COUNT = 12;
		private static final int FAMILY_COUNT = 40;
		private static final int DIVISION_COUNT = 10;
		private static final int SECTOR_COUNT = 5;
		private static final String[] CERTIFICATION_STANDARDS = {
				"iso-9001", "iso-14001", "iso-45001", "iso-50001", "iso-22301", "iso-27001"
		};

		private final RepositoryConnection connection;
		private final ValueFactory vf;

		private ProcurementFixture(RepositoryConnection connection) {
			this.connection = connection;
			this.vf = connection.getValueFactory();
		}

		private void addGeography() {
			for (int city = 0; city < CITY_COUNT; city++) {
				link(entity("city", city), "administrativeRegion", entity("region", city % REGION_COUNT));
			}
			for (int region = 0; region < REGION_COUNT; region++) {
				link(entity("region", region), "inCountry", entity("country", region % COUNTRY_COUNT));
			}
			for (int country = 0; country < COUNTRY_COUNT - 1; country++) {
				link(entity("country", country), "memberOfTradeArea", entity("trade-area", country % TRADE_AREA_COUNT));
			}
			for (int area = 0; area < TRADE_AREA_COUNT; area++) {
				IRI agreement = entity("trade-agreement", area);
				link(entity("trade-area", area), "procurementAgreement", agreement);
				if (area < TRADE_AREA_COUNT - 1) {
					link(agreement, "administeredBy", entity("trade-authority", area));
				}
			}
		}

		private void addSuppliers() {
			for (int issuer = 0; issuer < ISSUER_COUNT; issuer++) {
				if (issuer % 4 != 3) {
					link(entity("issuer", issuer), "accreditedBy", entity("accreditation-body", issuer / 4));
				}
			}
			for (int supplier = 0; supplier < SUPPLIER_COUNT; supplier++) {
				IRI supplierIri = entity("supplier", supplier);
				addSites(supplierIri, supplier);
				addCertificates(supplierIri, supplier);
			}
		}

		private void addSites(IRI supplierIri, int supplier) {
			int count = sitesForSupplier(supplier);
			for (int site = 0; site < count; site++) {
				int siteId = supplier * MAX_SITES_PER_SUPPLIER + site;
				IRI siteIri = entity("site", siteId);
				link(supplierIri, "operatesSite", siteIri);
				if (site < count - 1) {
					IRI address = entity("address", siteId);
					link(siteIri, "postalAddress", address);
					link(address, "locality", entity("city", siteId % CITY_COUNT));
					if (site % 2 == 0) {
						link(address, "streetAddress", vf.createLiteral((siteId + 1) + " Commerce Way"));
					}
				}
			}
		}

		private void addCertificates(IRI supplierIri, int supplier) {
			for (int standard = 0; standard < CERTIFICATION_STANDARDS.length; standard++) {
				IRI certificate = entity("certificate", supplier * CERTIFICATION_STANDARDS.length + standard);
				link(supplierIri, "holdsCertificate", certificate);
				link(certificate, "certifiesStandard",
						vf.createIRI(NS, "standard/" + CERTIFICATION_STANDARDS[standard]));
				if (standard < CERTIFICATION_STANDARDS.length - 1) {
					link(certificate, "issuedBy", entity("issuer", (supplier + standard) % ISSUER_COUNT));
				}
			}
		}

		private void addBuyers() {
			for (int buyer = 0; buyer < BUYER_COUNT; buyer++) {
				IRI buyerIri = entity("buyer", buyer);
				for (int contact = 0; contact < CONTACTS_PER_BUYER; contact++) {
					int contactId = buyer * CONTACTS_PER_BUYER + contact;
					IRI contactIri = entity("contact", contactId);
					link(buyerIri, "procurementContact", contactIri);
					if (contact < CONTACTS_PER_BUYER - 1) {
						link(contactIri, "email", vf.createLiteral("contact-" + contactId + "@procurement.example"));
					}
				}
			}
		}

		private void addCommodityTaxonomy() {
			for (int category = 0; category < CATEGORY_COUNT; category++) {
				link(entity("category", category), "commodityFamily", entity("family", category % FAMILY_COUNT));
			}
			for (int family = 0; family < FAMILY_COUNT; family++) {
				link(entity("family", family), "commodityDivision", entity("division", family % DIVISION_COUNT));
			}
			for (int division = 0; division < DIVISION_COUNT - 1; division++) {
				link(entity("division", division), "commoditySector", entity("sector", division % SECTOR_COUNT));
			}
		}

		private long addAwards(int awardCount) {
			IRI awardedTo = vf.createIRI(NS, "awardedTo");
			IRI authority = vf.createIRI(NS, "contractingAuthority");
			IRI commodityCategory = vf.createIRI(NS, "commodityCategory");
			IRI publishedThrough = vf.createIRI(NS, "publishedThrough");
			IRI buyerPortal = vf.createIRI(NS, "publication-channel/buyer-tender-portal");
			IRI nationalRegister = vf.createIRI(NS, "publication-channel/national-award-register");
			long distinctRows = 0;
			for (int award = 0; award < awardCount; award++) {
				IRI awardIri = entity("award", award);
				int supplier = award / 4 % SUPPLIER_COUNT;
				int buyer = (award / 2 + award / SUPPLIER_COUNT) % BUYER_COUNT;
				int category = (award / 3 + award / BUYER_COUNT) % CATEGORY_COUNT;
				connection.add(awardIri, awardedTo, entity("supplier", supplier));
				connection.add(awardIri, authority, entity("buyer", buyer));
				connection.add(awardIri, commodityCategory, entity("category", category));
				connection.add(awardIri, publishedThrough, buyerPortal);
				connection.add(awardIri, publishedThrough, nationalRegister);
				distinctRows += (long) sitesForSupplier(supplier) * CERTIFICATION_STANDARDS.length * CONTACTS_PER_BUYER;
			}
			return distinctRows;
		}

		private static int sitesForSupplier(int supplier) {
			return supplier % 2 == 0 ? 5 : MAX_SITES_PER_SUPPLIER;
		}

		private void link(IRI subject, String predicate, Value object) {
			connection.add(subject, vf.createIRI(NS, predicate), object);
		}

		private IRI entity(String type, int id) {
			return vf.createIRI(NS, type + "/" + id);
		}
	}
}
